-- KHAJI Pakhsh — Database schema proposal v1.1
-- Date: 2026-11-19
-- PostgreSQL 15+
-- DESIGN ARTIFACT ONLY. Review and test on an isolated staging database.
--
-- Scope: B2B catalog / lead-generation website; no checkout, payment, ERP,
-- advanced inventory, inquiries, analytics, or articles in this release.
-- SEO reference: Khaji Pakhsh SEO Development Guardrails V2.1 (Master).
--
-- Key decisions:
--   * Product ID is generated by PostgreSQL; product_code is immutable KHJ-<id>.
--   * SHA-256 is used for uploaded-file integrity/deduplication only, never as SKU.
--   * One current positive price per product, stored as integer Toman.
--   * Price-update Excel files match ONLY by product_code; never by row/name.
--   * SEO identity, canonical path, metadata, and lifecycle live in content_items.
--   * Page-builder content is revisioned JSONB with an application allow-list.
--   * Product/category/brand/page/price-list URLs share one unique path namespace.
--   * Sitemap and robots.txt are generated by the application/environment, not edited
--     as independent database records.
--
-- IMPORTANT: This file creates schema objects only. It does not create a database,
-- admin account, production secret, storage bucket, or deploy anything.

BEGIN;

-- -----------------------------------------------------------------------------
-- 01. Admin accounts and RBAC
-- -----------------------------------------------------------------------------
CREATE TABLE admin_users (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    display_name TEXT NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT admin_users_email_not_blank_ck CHECK (length(btrim(email)) > 3),
    CONSTRAINT admin_users_password_hash_not_blank_ck CHECK (length(password_hash) > 0)
);
CREATE UNIQUE INDEX admin_users_email_ci_uq ON admin_users (lower(email));

CREATE TABLE roles (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    label_fa TEXT NOT NULL,
    CONSTRAINT roles_code_format_ck CHECK (code ~ '^[a-z][a-z0-9_]*$')
);

CREATE TABLE permissions (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    label_fa TEXT NOT NULL,
    CONSTRAINT permissions_code_format_ck CHECK (code ~ '^[a-z][a-z0-9_.]*$')
);

CREATE TABLE admin_user_roles (
    admin_user_id BIGINT NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT,
    role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
    PRIMARY KEY (admin_user_id, role_id)
);

CREATE TABLE role_permissions (
    role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
    permission_id BIGINT NOT NULL REFERENCES permissions(id) ON DELETE RESTRICT,
    PRIMARY KEY (role_id, permission_id)
);

-- Seed role/permission vocabulary. No administrator account is created here.
