    'dashboard.read','products.read','products.write','categories.read',
    'categories.write','brands.read','brands.write','media.read','media.manage'
)
WHERE r.code = 'catalog_manager';

INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM roles r JOIN permissions p ON p.code IN (
    'dashboard.read','products.read','categories.read','brands.read',
    'prices.read','prices.write','prices.import','price_lists.read','price_lists.publish'
)
WHERE r.code = 'price_manager';

INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM roles r JOIN permissions p ON p.code IN (
    'dashboard.read','products.read','categories.read','brands.read',
    'price_lists.read','pages.read','seo.manage'
)
WHERE r.code = 'seo_editor';

INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM roles r JOIN permissions p ON p.code IN (
    'dashboard.read','media.read','media.manage','pages.read','pages.write',
    'pages.publish','navigation.manage'
)
WHERE r.code = 'content_editor';

-- -----------------------------------------------------------------------------
-- 02. Media library. Binary files live in object/file storage, not PostgreSQL.
-- -----------------------------------------------------------------------------
CREATE TABLE media_assets (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    storage_key TEXT NOT NULL UNIQUE,
    original_filename TEXT,
    mime_type TEXT NOT NULL,
    byte_size BIGINT NOT NULL,
    sha256_hex CHAR(64),
    width_px INTEGER,
    height_px INTEGER,
    default_alt_text TEXT,
    uploaded_by BIGINT REFERENCES admin_users(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT media_storage_key_not_blank_ck CHECK (length(btrim(storage_key)) > 0),
    CONSTRAINT media_mime_not_blank_ck CHECK (length(btrim(mime_type)) > 0),
    CONSTRAINT media_byte_size_ck CHECK (byte_size > 0),
    CONSTRAINT media_width_ck CHECK (width_px IS NULL OR width_px > 0),
    CONSTRAINT media_height_ck CHECK (height_px IS NULL OR height_px > 0),
    CONSTRAINT media_sha_format_ck CHECK (sha256_hex IS NULL OR sha256_hex ~ '^[0-9a-f]{64}$')
);
CREATE INDEX media_assets_sha_ix ON media_assets(sha256_hex) WHERE sha256_hex IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 03. Shared content identity + SEO source of truth.
-- One row per public entity; canonical_path is unique across ALL content types.
-- Slugs may be Persian or Latin. Normalize Unicode and slug policy in the app.
-- -----------------------------------------------------------------------------
CREATE TABLE content_items (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    content_type TEXT NOT NULL,
    slug TEXT NOT NULL,
    canonical_path TEXT NOT NULL,

    h1_override TEXT,
    seo_title TEXT,
    meta_description TEXT,
    canonical_url_override TEXT,
    robots_index BOOLEAN NOT NULL DEFAULT FALSE,
    robots_follow BOOLEAN NOT NULL DEFAULT TRUE,
    og_title TEXT,
    og_description TEXT,
    og_image_media_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    og_image_alt_text TEXT,

    status TEXT NOT NULL DEFAULT 'draft',
    published_at TIMESTAMPTZ,
    content_updated_at TIMESTAMPTZ,
    removed_http_status SMALLINT NOT NULL DEFAULT 404,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT content_items_type_ck CHECK (content_type IN ('page','category','brand','product','price_list')),
    CONSTRAINT content_items_status_ck CHECK (status IN ('draft','review','published','unpublished','deleted','redirected')),
    CONSTRAINT content_items_type_pair_uq UNIQUE (id, content_type),
    CONSTRAINT content_items_slug_not_blank_ck CHECK (
        length(btrim(slug)) > 0
        AND slug = btrim(slug)
        AND position('/' in slug) = 0
        AND position('?' in slug) = 0
        AND position('#' in slug) = 0
        AND position(' ' in slug) = 0
    ),
    CONSTRAINT content_items_path_ck CHECK (
        left(canonical_path, 1) = '/'
        AND position('?' in canonical_path) = 0
        AND position('#' in canonical_path) = 0
        AND position('//' in canonical_path) = 0
    ),
    CONSTRAINT content_items_canonical_override_ck CHECK (
        canonical_url_override IS NULL OR canonical_url_override ~* '^https://'
    ),
    CONSTRAINT content_items_published_date_ck CHECK (status <> 'published' OR published_at IS NOT NULL),
    CONSTRAINT content_items_nonpublished_noindex_ck CHECK (status = 'published' OR robots_index = FALSE),
    CONSTRAINT content_items_removed_status_ck CHECK (removed_http_status IN (404,410))
);
CREATE UNIQUE INDEX content_items_path_ci_uq ON content_items(lower(canonical_path));
CREATE INDEX content_items_type_status_ix ON content_items(content_type, status);
CREATE INDEX content_items_sitemap_ix ON content_items(status, robots_index, content_updated_at)
    WHERE status = 'published' AND robots_index = TRUE;

COMMENT ON TABLE content_items IS
'Common SEO and URL source of truth for pages, categories, brands, products and price lists. Sitemap/robots are generated by the application.';
COMMENT ON COLUMN content_items.content_updated_at IS
'Update only for meaningful public content changes; sitemap lastmod must not use routine admin updated_at.';
COMMENT ON COLUMN content_items.canonical_url_override IS
'Optional absolute HTTPS override only when justified. Otherwise Next.js builds canonical from environment domain + canonical_path.';

-- -----------------------------------------------------------------------------
-- 04. Catalog: categories, brands, products.
-- -----------------------------------------------------------------------------
CREATE TABLE categories (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    content_item_id BIGINT NOT NULL UNIQUE,
    content_type TEXT NOT NULL DEFAULT 'category' CHECK (content_type = 'category'),
    parent_id BIGINT REFERENCES categories(id) ON DELETE RESTRICT,
    title TEXT NOT NULL,
    description TEXT,
    hero_media_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    hero_alt_text TEXT NOT NULL DEFAULT '',
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (content_item_id, content_type)
        REFERENCES content_items(id, content_type) ON DELETE RESTRICT,
    CONSTRAINT categories_title_not_blank_ck CHECK (length(btrim(title)) > 0),
    CONSTRAINT categories_parent_self_ck CHECK (parent_id IS NULL OR parent_id <> id)
);
CREATE INDEX categories_parent_ix ON categories(parent_id);
CREATE INDEX categories_sort_ix ON categories(sort_order);

CREATE TABLE brands (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    content_item_id BIGINT NOT NULL UNIQUE,
    content_type TEXT NOT NULL DEFAULT 'brand' CHECK (content_type = 'brand'),
    name_fa TEXT NOT NULL,
    name_en TEXT,
    logo_media_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    logo_alt_text TEXT NOT NULL DEFAULT '',
    description TEXT,
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (content_item_id, content_type)
        REFERENCES content_items(id, content_type) ON DELETE RESTRICT,
    CONSTRAINT brands_name_not_blank_ck CHECK (length(btrim(name_fa)) > 0)
);
CREATE INDEX brands_sort_ix ON brands(sort_order);

CREATE TABLE products (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    content_item_id BIGINT NOT NULL UNIQUE,
    content_type TEXT NOT NULL DEFAULT 'product' CHECK (content_type = 'product'),
    product_code TEXT GENERATED ALWAYS AS ('KHJ-' || id::text) STORED UNIQUE,
    name TEXT NOT NULL,
    brand_id BIGINT REFERENCES brands(id) ON DELETE RESTRICT,
    primary_category_id BIGINT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
    sale_unit TEXT NOT NULL DEFAULT 'عدد',
    short_description TEXT,
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (content_item_id, content_type)
        REFERENCES content_items(id, content_type) ON DELETE RESTRICT,
    CONSTRAINT products_name_not_blank_ck CHECK (length(btrim(name)) > 0),
    CONSTRAINT products_sale_unit_not_blank_ck CHECK (length(btrim(sale_unit)) > 0)
);
CREATE INDEX products_brand_ix ON products(brand_id);
CREATE INDEX products_primary_category_ix ON products(primary_category_id);

-- Additional categories; primary_category_id is the single primary category.
CREATE TABLE product_categories (
    product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    category_id BIGINT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
    PRIMARY KEY (product_id, category_id)
);
CREATE INDEX product_categories_category_ix ON product_categories(category_id);

-- Typed technical attributes; category/type consistency is validated by the service.
CREATE TABLE attributes (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    label_fa TEXT NOT NULL,
    data_type TEXT NOT NULL,
    unit_label TEXT,
    CONSTRAINT attributes_code_ck CHECK (code ~ '^[a-z][a-z0-9_]*$'),
    CONSTRAINT attributes_type_ck CHECK (data_type IN ('text','number','boolean'))
);

CREATE TABLE category_attributes (
    category_id BIGINT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
    attribute_id BIGINT NOT NULL REFERENCES attributes(id) ON DELETE RESTRICT,
    is_required_for_publication BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (category_id, attribute_id)
);

CREATE TABLE product_attribute_values (
    product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    attribute_id BIGINT NOT NULL REFERENCES attributes(id) ON DELETE RESTRICT,
    text_value TEXT,
    number_value NUMERIC(20,4),
    boolean_value BOOLEAN,
    PRIMARY KEY (product_id, attribute_id),
    CONSTRAINT product_attribute_one_value_ck CHECK (
        num_nonnulls(text_value, number_value, boolean_value) = 1
    )
);

-- Alt text belongs to the image placement, not only to the binary media file.
CREATE TABLE product_media (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    media_id BIGINT NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,
    alt_text TEXT NOT NULL DEFAULT '',
    is_decorative BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    is_primary BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT product_media_decorative_alt_ck CHECK (NOT is_decorative OR alt_text = '')
);
CREATE UNIQUE INDEX product_media_one_primary_ix ON product_media(product_id) WHERE is_primary = TRUE;
CREATE INDEX product_media_media_ix ON product_media(media_id);

-- -----------------------------------------------------------------------------
-- 05. Current prices, Excel staging and immutable price history.
-- -----------------------------------------------------------------------------
CREATE TABLE price_import_batches (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    source_file_media_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    created_by BIGINT NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT,
    status TEXT NOT NULL DEFAULT 'uploaded',
    total_rows INTEGER NOT NULL DEFAULT 0,
    valid_rows INTEGER NOT NULL DEFAULT 0,
    error_rows INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    validated_at TIMESTAMPTZ,
    applied_at TIMESTAMPTZ,
    CONSTRAINT price_batch_status_ck CHECK (status IN ('uploaded','validated','applied','rejected','failed')),
    CONSTRAINT price_batch_counts_ck CHECK (total_rows >= 0 AND valid_rows >= 0 AND error_rows >= 0)
);

CREATE TABLE price_import_rows (
    batch_id BIGINT NOT NULL REFERENCES price_import_batches(id) ON DELETE RESTRICT,
    row_number INTEGER NOT NULL,
    raw_product_code TEXT NOT NULL DEFAULT '',
    product_id BIGINT REFERENCES products(id) ON DELETE RESTRICT,
    proposed_amount_toman BIGINT,
    validation_status TEXT NOT NULL DEFAULT 'pending',
    error_code TEXT,
    error_message TEXT,
    PRIMARY KEY (batch_id, row_number),
    CONSTRAINT price_import_row_num_ck CHECK (row_number > 0),
    CONSTRAINT price_import_amount_ck CHECK (proposed_amount_toman IS NULL OR proposed_amount_toman > 0),
    CONSTRAINT price_import_row_status_ck CHECK (
        validation_status IN ('pending','valid','invalid','duplicate','applied')
    )
);
CREATE INDEX price_import_rows_product_ix ON price_import_rows(product_id);
CREATE INDEX price_import_rows_code_ix ON price_import_rows(batch_id, raw_product_code);
-- Duplicate/unknown product codes are retained as validation errors; service rejects the batch.

-- Exactly one current price at most per product. No row means quote required.
-- Amount is integer Toman; price tiers/currency conversion are outside V1.
CREATE TABLE product_prices (
    product_id BIGINT PRIMARY KEY REFERENCES products(id) ON DELETE RESTRICT,
    amount_toman BIGINT NOT NULL,
    updated_by BIGINT REFERENCES admin_users(id) ON DELETE RESTRICT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT product_price_positive_ck CHECK (amount_toman > 0)
);

CREATE TABLE price_history (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    old_amount_toman BIGINT,
    new_amount_toman BIGINT,
    change_source TEXT NOT NULL,
    import_batch_id BIGINT REFERENCES price_import_batches(id) ON DELETE RESTRICT,
    changed_by BIGINT NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT,
    changed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT price_history_old_positive_ck CHECK (old_amount_toman IS NULL OR old_amount_toman > 0),
    CONSTRAINT price_history_new_positive_ck CHECK (new_amount_toman IS NULL OR new_amount_toman > 0),
    CONSTRAINT price_history_changed_ck CHECK (old_amount_toman IS DISTINCT FROM new_amount_toman),
    CONSTRAINT price_history_source_ck CHECK (change_source IN ('manual','excel','rollback','clear')),
    CONSTRAINT price_history_batch_source_ck CHECK (
        (change_source = 'excel' AND import_batch_id IS NOT NULL)
        OR (change_source <> 'excel' AND import_batch_id IS NULL)
    )
);
CREATE INDEX price_history_product_time_ix ON price_history(product_id, changed_at DESC);

-- -----------------------------------------------------------------------------
-- 06. Price lists generated from catalog data.
-- HTML pages read current product_prices; publications are immutable snapshots
-- for dated exports/archive. No independently typed product price is stored here.
-- -----------------------------------------------------------------------------
CREATE TABLE price_lists (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    content_item_id BIGINT NOT NULL UNIQUE,
    content_type TEXT NOT NULL DEFAULT 'price_list' CHECK (content_type = 'price_list'),
    title TEXT NOT NULL,
    category_id BIGINT REFERENCES categories(id) ON DELETE RESTRICT,
    brand_id BIGINT REFERENCES brands(id) ON DELETE RESTRICT,
    include_descendants BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (content_item_id, content_type)
        REFERENCES content_items(id, content_type) ON DELETE RESTRICT,
    CONSTRAINT price_lists_title_not_blank_ck CHECK (length(btrim(title)) > 0)
);
CREATE INDEX price_lists_category_ix ON price_lists(category_id);
CREATE INDEX price_lists_brand_ix ON price_lists(brand_id);

CREATE TABLE price_list_publications (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    price_list_id BIGINT NOT NULL REFERENCES price_lists(id) ON DELETE RESTRICT,
    version_number INTEGER NOT NULL CHECK (version_number > 0),
    generated_by BIGINT NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT,
    published_by BIGINT NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT,
    generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (price_list_id, version_number)
);
CREATE INDEX price_publications_latest_ix ON price_list_publications(price_list_id, version_number DESC);

CREATE TABLE price_list_publication_items (
    publication_id BIGINT NOT NULL REFERENCES price_list_publications(id) ON DELETE RESTRICT,
    product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    product_code_snapshot TEXT NOT NULL,
    product_name_snapshot TEXT NOT NULL,
    product_path_snapshot TEXT NOT NULL,
    brand_name_snapshot TEXT,
    sale_unit_snapshot TEXT NOT NULL,
    amount_toman_snapshot BIGINT NOT NULL,
    PRIMARY KEY (publication_id, product_id),
    CONSTRAINT price_list_snapshot_amount_ck CHECK (amount_toman_snapshot > 0),
    CONSTRAINT price_list_snapshot_path_ck CHECK (left(product_path_snapshot,1) = '/')
);

-- -----------------------------------------------------------------------------
-- 07. Controlled page builder and revision history.
-- Blocks are structured JSON only; application validates an allow-list of block
-- types/fields and media references. Never execute arbitrary HTML/JS from JSONB.
-- -----------------------------------------------------------------------------
CREATE TABLE pages (
    content_item_id BIGINT PRIMARY KEY,
    content_type TEXT NOT NULL DEFAULT 'page' CHECK (content_type = 'page'),
    page_type TEXT NOT NULL DEFAULT 'static',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (content_item_id, content_type)
        REFERENCES content_items(id, content_type) ON DELETE RESTRICT,
    CONSTRAINT pages_type_ck CHECK (page_type IN ('home','static','landing'))
);
CREATE UNIQUE INDEX pages_one_home_ix ON pages(page_type) WHERE page_type = 'home';

CREATE TABLE page_revisions (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    page_content_item_id BIGINT NOT NULL REFERENCES pages(content_item_id) ON DELETE RESTRICT,
    revision_number INTEGER NOT NULL,
    title TEXT NOT NULL,
    h1_override TEXT,
    blocks JSONB NOT NULL DEFAULT '[]'::jsonb,
    seo_title TEXT,
    meta_description TEXT,
    canonical_url_override TEXT,
    robots_index BOOLEAN NOT NULL DEFAULT FALSE,
    robots_follow BOOLEAN NOT NULL DEFAULT TRUE,
    og_title TEXT,
    og_description TEXT,
    og_image_media_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    og_image_alt_text TEXT,
    revision_status TEXT NOT NULL DEFAULT 'draft',
    created_by BIGINT NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT,
    reviewed_by BIGINT REFERENCES admin_users(id) ON DELETE RESTRICT,
    published_by BIGINT REFERENCES admin_users(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at TIMESTAMPTZ,
    UNIQUE (page_content_item_id, revision_number),
    CONSTRAINT page_revision_json_array_ck CHECK (jsonb_typeof(blocks) = 'array'),
    CONSTRAINT page_revision_status_ck CHECK (revision_status IN ('draft','review','published','archived')),
    CONSTRAINT page_revision_published_date_ck CHECK (revision_status <> 'published' OR published_at IS NOT NULL),
    CONSTRAINT page_revision_canonical_ck CHECK (
        canonical_url_override IS NULL OR canonical_url_override ~* '^https://'
    )
);
CREATE UNIQUE INDEX page_one_published_revision_ix
    ON page_revisions(page_content_item_id) WHERE revision_status = 'published';
CREATE INDEX page_revisions_history_ix ON page_revisions(page_content_item_id, revision_number DESC);

CREATE TABLE page_revision_media (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    revision_id BIGINT NOT NULL REFERENCES page_revisions(id) ON DELETE RESTRICT,
    block_key TEXT NOT NULL,
    media_id BIGINT NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,
    alt_text TEXT NOT NULL DEFAULT '',
    is_decorative BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT page_revision_media_block_key_ck CHECK (length(btrim(block_key)) > 0),
    CONSTRAINT page_revision_media_decorative_alt_ck CHECK (NOT is_decorative OR alt_text = '')
);
CREATE INDEX page_revision_media_revision_ix ON page_revision_media(revision_id, block_key, sort_order);

-- -----------------------------------------------------------------------------
-- 08. Navigation and global settings.
-- Internal navigation links point to content_item IDs so slug changes do not
-- leave stale hard-coded internal URLs. External links must be HTTPS.
-- -----------------------------------------------------------------------------
CREATE TABLE navigation_menus (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    label TEXT NOT NULL,
    CONSTRAINT nav_menu_code_ck CHECK (code ~ '^[a-z][a-z0-9_]*$')
);

CREATE TABLE navigation_items (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    menu_id BIGINT NOT NULL REFERENCES navigation_menus(id) ON DELETE RESTRICT,
    parent_item_id BIGINT,
    label TEXT NOT NULL,
    target_content_item_id BIGINT REFERENCES content_items(id) ON DELETE RESTRICT,
    external_url TEXT,
    sort_order INTEGER NOT NULL DEFAULT 0,
    is_visible BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE (menu_id, id),
    FOREIGN KEY (menu_id, parent_item_id) REFERENCES navigation_items(menu_id, id) ON DELETE RESTRICT,
    CONSTRAINT nav_item_target_one_ck CHECK (num_nonnulls(target_content_item_id, external_url) = 1),
    CONSTRAINT nav_item_external_https_ck CHECK (external_url IS NULL OR external_url ~* '^https://'),
    CONSTRAINT nav_item_not_own_parent_ck CHECK (parent_item_id IS NULL OR parent_item_id <> id),
    CONSTRAINT nav_item_label_not_blank_ck CHECK (length(btrim(label)) > 0)
);
CREATE INDEX nav_items_order_ix ON navigation_items(menu_id, parent_item_id, sort_order);

CREATE TABLE site_settings (
    setting_key TEXT PRIMARY KEY,
    setting_value JSONB NOT NULL,
    updated_by BIGINT REFERENCES admin_users(id) ON DELETE RESTRICT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT site_settings_key_ck CHECK (setting_key ~ '^[a-z][a-z0-9_.]*$')
);

-- -----------------------------------------------------------------------------
-- 09. SEO redirects. Canonical path collisions and direct chains are guarded
-- below; full multi-hop cycle detection and target validation are service rules.
-- -----------------------------------------------------------------------------
CREATE TABLE seo_redirects (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    source_path TEXT NOT NULL,
    target_path TEXT NOT NULL,
    status_code SMALLINT NOT NULL DEFAULT 301,
    reason TEXT,
    created_by BIGINT REFERENCES admin_users(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT seo_redirect_source_path_ck CHECK (
        left(source_path,1) = '/' AND position('?' in source_path) = 0 AND position('#' in source_path) = 0
    ),
    CONSTRAINT seo_redirect_target_path_ck CHECK (
        left(target_path,1) = '/' AND position('?' in target_path) = 0 AND position('#' in target_path) = 0
    ),
    CONSTRAINT seo_redirect_no_self_ck CHECK (source_path <> target_path),
    CONSTRAINT seo_redirect_code_ck CHECK (status_code IN (301,308))
);

CREATE UNIQUE INDEX seo_redirects_source_ci_uq ON seo_redirects(lower(source_path));

CREATE FUNCTION khaji_guard_content_path() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.status <> 'redirected' AND EXISTS (
        SELECT 1 FROM seo_redirects r WHERE lower(r.source_path) = lower(NEW.canonical_path)
    ) THEN
        RAISE EXCEPTION 'Canonical path % is already registered as a redirect source', NEW.canonical_path;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER guard_content_path_insert
BEFORE INSERT ON content_items
FOR EACH ROW EXECUTE FUNCTION khaji_guard_content_path();
CREATE TRIGGER guard_content_path_update
BEFORE UPDATE OF canonical_path, status ON content_items
FOR EACH ROW EXECUTE FUNCTION khaji_guard_content_path();

CREATE FUNCTION khaji_guard_redirect_path() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM content_items c
        WHERE lower(c.canonical_path) = lower(NEW.source_path) AND c.status <> 'redirected'
    ) THEN
        RAISE EXCEPTION 'Redirect source % is still an active canonical content path', NEW.source_path;
    END IF;
    IF EXISTS (
        SELECT 1 FROM seo_redirects r
        WHERE lower(r.source_path) = lower(NEW.target_path) AND r.id IS DISTINCT FROM NEW.id
    ) THEN
        RAISE EXCEPTION 'Redirect target % is itself a redirect source; redirect chains are not allowed', NEW.target_path;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER guard_redirect_path_insert
BEFORE INSERT ON seo_redirects
FOR EACH ROW EXECUTE FUNCTION khaji_guard_redirect_path();
CREATE TRIGGER guard_redirect_path_update
BEFORE UPDATE OF source_path, target_path ON seo_redirects
FOR EACH ROW EXECUTE FUNCTION khaji_guard_redirect_path();

-- -----------------------------------------------------------------------------
-- 10. Append-only audit log.
-- -----------------------------------------------------------------------------
CREATE TABLE audit_logs (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    actor_type TEXT NOT NULL DEFAULT 'admin',
    actor_user_id BIGINT REFERENCES admin_users(id) ON DELETE RESTRICT,
    entity_type TEXT NOT NULL,
    entity_id BIGINT,
    action TEXT NOT NULL,
    before_data JSONB,
    after_data JSONB,
    request_id TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT audit_actor_type_ck CHECK (actor_type IN ('admin','system')),
    CONSTRAINT audit_actor_consistency_ck CHECK (
        (actor_type = 'admin' AND actor_user_id IS NOT NULL)
        OR (actor_type = 'system' AND actor_user_id IS NULL)
    ),
    CONSTRAINT audit_entity_not_blank_ck CHECK (length(btrim(entity_type)) > 0),
    CONSTRAINT audit_action_not_blank_ck CHECK (length(btrim(action)) > 0)
);
CREATE INDEX audit_entity_time_ix ON audit_logs(entity_type, entity_id, created_at DESC);
CREATE INDEX audit_actor_time_ix ON audit_logs(actor_user_id, created_at DESC);

-- -----------------------------------------------------------------------------
-- 11. Shared trigger utilities and immutability guards.
-- -----------------------------------------------------------------------------
CREATE FUNCTION khaji_touch_updated_at() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER touch_admin_users BEFORE UPDATE ON admin_users
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();
CREATE TRIGGER touch_content_items BEFORE UPDATE ON content_items
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();
CREATE TRIGGER touch_categories BEFORE UPDATE ON categories
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();
CREATE TRIGGER touch_brands BEFORE UPDATE ON brands
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();
CREATE TRIGGER touch_products BEFORE UPDATE ON products
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();
CREATE TRIGGER touch_product_prices BEFORE UPDATE ON product_prices
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();
CREATE TRIGGER touch_price_lists BEFORE UPDATE ON price_lists
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();
CREATE TRIGGER touch_pages BEFORE UPDATE ON pages
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();
CREATE TRIGGER touch_site_settings BEFORE UPDATE ON site_settings
FOR EACH ROW EXECUTE FUNCTION khaji_touch_updated_at();

CREATE FUNCTION khaji_reject_immutable_change() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'Table % is append-only; % is not allowed', TG_TABLE_NAME, TG_OP;
    RETURN OLD;
END;
$$;
CREATE TRIGGER price_history_append_only
BEFORE UPDATE OR DELETE ON price_history
FOR EACH ROW EXECUTE FUNCTION khaji_reject_immutable_change();
CREATE TRIGGER price_publications_append_only
BEFORE UPDATE OR DELETE ON price_list_publications
FOR EACH ROW EXECUTE FUNCTION khaji_reject_immutable_change();
CREATE TRIGGER price_publication_items_append_only
BEFORE UPDATE OR DELETE ON price_list_publication_items
FOR EACH ROW EXECUTE FUNCTION khaji_reject_immutable_change();
CREATE TRIGGER audit_logs_append_only
BEFORE UPDATE OR DELETE ON audit_logs
FOR EACH ROW EXECUTE FUNCTION khaji_reject_immutable_change();

COMMIT;

-- -----------------------------------------------------------------------------
-- REQUIRED APPLICATION / OPERATIONS CONTRACTS (not all are plain FK rules)
-- -----------------------------------------------------------------------------
-- A. Product creation and stable code
--   1. Create content_items(content_type='product', status='draft', robots_index=false)
--      and products in ONE transaction.
--   2. Do not accept client-supplied products.id or product_code.
--   3. Read generated product_code using INSERT ... RETURNING id, product_code.
--   4. Code format is KHJ-<id>; gaps are normal and codes are never reused.
--   5. SHA-256 is only a file checksum/deduplication aid in media_assets.
--
-- B. Excel price updates
--   1. Require product_code in every price-update row; match exact normalized code.
--   2. Unknown, duplicate, blank, malformed, or non-positive rows are validation errors.
--   3. Never match by product name, row number, mutable slug, or supplier text.
--   4. Never create products from a price-update file. New products get codes first;
--      export the generated code map, then use those codes in future price sheets.
--   5. Preview all rows; apply only a fully valid batch in one DB transaction.
--   6. Update product_prices, insert price_history, and mark batch applied atomically.
--   7. Rollback must compare current values with the values originally applied;
--      do not overwrite a newer manual/import change silently.
--
-- C. SEO / content lifecycle
--   1. content_items is the single source of truth for URL, slug, common SEO metadata,
--      robots policy and publication state for all public content entities.
--   2. Slug language is a project policy decision (Persian or Latin); this schema
--      accepts both. Normalize Unicode (NFC), Persian/Arabic character variants,
--      whitespace and separators consistently in the application.
--   3. canonical_path is globally unique across pages/categories/brands/products/
--      price lists. Do not publish a route before checking reserved Next.js paths.
--   4. canonical_url_override must be an approved absolute HTTPS URL. Otherwise build
--      canonical from the environment's canonical domain + canonical_path.
--   5. Draft/review/unpublished/deleted/redirected content must not be indexable.
--      Noindex/robots is not access control; private previews require authentication.
--   6. On slug/path change: show warning, update canonical_path, create a relevant
--      301/308 redirect from old path in the same transaction, and verify target.
--      Navigation uses content_item IDs; page-block internal links should also use IDs.
--   7. Reject redirect chains and cycles; validate target is a live relevant canonical
--      page. For removed content without replacement, return configured 404 or 410.
--   8. Sitemap includes only published, indexable canonical paths; exclude noindex,
--      redirects, deleted/unpublished, and non-self-canonical URLs. Build absolute URLs
--      using the active environment domain. Use content_updated_at for truthful lastmod.
--   9. robots.txt is generated by the application/environment. It is not an editable
--      content table and must not be treated as security. Review demo/staging/production
--      indexing separately before launch.
--  10. Structured data (Organization, BreadcrumbList, Product, Article, VideoObject,
--      etc.) is generated from verified source data and visible content as appropriate;
--      do not store hand-authored duplicate JSON-LD or fabricate price/stock/reviews.
--  11. Metadata preview is computed in the dashboard. Validate title/description,
--      H1, canonical, robots, OG and image alt before publish; no fixed character
--      density/keyword-ratio rule is enforced by this schema.
--  12. Image alt is placement-specific: product_media, category hero, brand logo,
--      page_revision_media and OG image. Empty alt is valid for decorative images only.
--
-- D. Page builder and SEO content
--   1. blocks JSONB must be validated against an allow-list of approved block types
--      and schemas. Do not permit arbitrary scripts/HTML from dashboard content.
--   2. Preserve the approved Homepage structure and visual design; do not add blog,
--      video, featured-product or other sections without explicit approval.
--   3. When publishing a page revision, copy its SEO snapshot into content_items
--      in the same transaction and update content_updated_at only for meaningful changes.
--   4. FAQ/slider/homepage section data can live inside structured approved blocks;
--      article/blog tables are intentionally deferred to Phase 2.
--
-- E. Application rendering and technical SEO
--   1. Use Next.js App Router Metadata API; server-render/prerender important content
--      so primary content and links exist in response HTML without client interaction.
--   2. metadataBase, canonical host and environment policy come from deployment config,
--      not a hard-coded demo URL or an arbitrary admin field.
--   3. Generate XML sitemap and robots.txt from database + environment rules; test
--      response status, canonical, robots, internal links, 404/410 and redirects.
--   4. Generate structured data only when the real page/data qualifies; test output.
--
-- F. Security, roles, backup and deployment
--   1. Hash passwords with a vetted authentication library; never store plaintext.
--   2. Check permissions server-side for every action; hiding a UI button is insufficient.
--   3. Use separate migration and least-privilege runtime DB roles in production.
--   4. Protect price_history, price-list snapshots and audit_logs with DB privileges;
--      append-only triggers here provide an additional safeguard.
--   5. Store images/files outside PostgreSQL; validate actual MIME/content, size and
--      authorization on upload. sha256_hex is for file integrity/dedup only.
--   6. Back up PostgreSQL and media storage together; test restoration. Backup files
--      and schedules are infrastructure concerns, not rows in this schema.
--   7. Authentication session storage depends on the selected auth library; add its
--      session table only if that library requires database-backed sessions.
--
-- G. Explicitly deferred to Phase 2 (not created here)
--   inquiries/CRM, analytics events, articles/blog, advanced stock ledger, checkout,
--   customer accounts, online payment, invoicing and ERP integrations.
